{
  "version": 1,
  "id": "example_before_after",
  "name": "Before / after",
  "settings": {
    "width": 1920,
    "height": 1080,
    "fps": 30,
    "theme": "dark",
    "fonts": {
      "main": "Inter",
      "heading": "",
      "code": "JetBrains Mono",
      "families": []
    }
  },
  "variables": {
    "Before address": "https://example.com",
    "After address": "https://example.org"
  },
  "nodes": [
    {
      "id": "before-session",
      "type": "browser.open",
      "position": {
        "x": 0,
        "y": 0
      },
      "params": {
        "viewportWidth": 1920,
        "viewportHeight": 1080,
        "dpr": 2,
        "mobile": false,
        "userAgent": "",
        "locale": "en-US",
        "timezone": "",
        "colorScheme": "light",
        "captureScale": 1
      }
    },
    {
      "id": "before-open",
      "type": "browser.navigate",
      "position": {
        "x": 300,
        "y": 0
      },
      "params": {
        "url": "{{Before address}}",
        "waitUntil": "load",
        "after": 2500
      }
    },
    {
      "id": "before-start",
      "type": "browser.startRecording",
      "position": {
        "x": 600,
        "y": 0
      },
      "params": {}
    },
    {
      "id": "before-record",
      "type": "capture.record",
      "position": {
        "x": 900,
        "y": 0
      },
      "params": {
        "fps": 30,
        "quality": 90,
        "establishMs": 700,
        "endTailMs": 2500,
        "cursor": "synthetic",
        "showActions": false,
        "mutates": ""
      }
    },
    {
      "id": "before-camera",
      "type": "camera.autoZoom",
      "position": {
        "x": 900,
        "y": 200
      },
      "params": {
        "zoom": false,
        "maxScale": 1.74,
        "hold": 1300,
        "speed": 1.25,
        "style": "classic",
        "backdrop": "glaze",
        "frame": "none",
        "frameTheme": "light",
        "addressBar": true,
        "motionBlur": true
      }
    },
    {
      "id": "before-label",
      "type": "fx.core.lower-third",
      "position": {
        "x": 900,
        "y": 422
      },
      "params": {
        "title": "Before",
        "subtitle": "{{Before address}}",
        "position": "bottom-left",
        "accent": "#a78bfa",
        "color": "#fafafa",
        "panel": "rgba(10,10,12,0.72)",
        "fontFamily": "",
        "clipDuration": 120,
        "envelope": {}
      }
    },
    {
      "id": "before-stack",
      "type": "timeline.stack",
      "position": {
        "x": 1200,
        "y": 0
      },
      "params": {
        "duration": "first",
        "offsetsMs": "",
        "keepLayout": false
      }
    },
    {
      "id": "after-session",
      "type": "browser.open",
      "position": {
        "x": 0,
        "y": 850
      },
      "params": {
        "viewportWidth": 1920,
        "viewportHeight": 1080,
        "dpr": 2,
        "mobile": false,
        "userAgent": "",
        "locale": "en-US",
        "timezone": "",
        "colorScheme": "light",
        "captureScale": 1
      }
    },
    {
      "id": "after-open",
      "type": "browser.navigate",
      "position": {
        "x": 300,
        "y": 850
      },
      "params": {
        "url": "{{After address}}",
        "waitUntil": "load",
        "after": 2500
      }
    },
    {
      "id": "after-start",
      "type": "browser.startRecording",
      "position": {
        "x": 600,
        "y": 850
      },
      "params": {}
    },
    {
      "id": "after-record",
      "type": "capture.record",
      "position": {
        "x": 900,
        "y": 850
      },
      "params": {
        "fps": 30,
        "quality": 90,
        "establishMs": 700,
        "endTailMs": 2500,
        "cursor": "synthetic",
        "showActions": false,
        "mutates": ""
      }
    },
    {
      "id": "after-camera",
      "type": "camera.autoZoom",
      "position": {
        "x": 900,
        "y": 1050
      },
      "params": {
        "zoom": false,
        "maxScale": 1.74,
        "hold": 1300,
        "speed": 1.25,
        "style": "classic",
        "backdrop": "glaze",
        "frame": "none",
        "frameTheme": "light",
        "addressBar": true,
        "motionBlur": true
      }
    },
    {
      "id": "after-label",
      "type": "fx.core.lower-third",
      "position": {
        "x": 900,
        "y": 1272
      },
      "params": {
        "title": "After",
        "subtitle": "{{After address}}",
        "position": "bottom-left",
        "accent": "#a78bfa",
        "color": "#fafafa",
        "panel": "rgba(10,10,12,0.72)",
        "fontFamily": "",
        "clipDuration": 120,
        "envelope": {}
      }
    },
    {
      "id": "after-stack",
      "type": "timeline.stack",
      "position": {
        "x": 1200,
        "y": 850
      },
      "params": {
        "duration": "first",
        "offsetsMs": "",
        "keepLayout": false
      }
    },
    {
      "id": "wipe",
      "type": "transition.core.wipe",
      "position": {
        "x": 1500,
        "y": 510
      },
      "params": {
        "direction": "from-left",
        "durationInFrames": 24,
        "keepWhole": false
      }
    },
    {
      "id": "render",
      "type": "output.render",
      "position": {
        "x": 1800,
        "y": 510
      },
      "params": {
        "fileName": "{{Project name}}",
        "codec": "h264",
        "crf": 18,
        "variants": [
          "16:9"
        ],
        "reframe": "follow",
        "scale": 1,
        "chapters": true,
        "chapterList": false,
        "gl": "angle"
      }
    }
  ],
  "edges": [
    {
      "id": "before-session.session->before-open.session",
      "source": "before-session",
      "sourceHandle": "session",
      "target": "before-open",
      "targetHandle": "session"
    },
    {
      "id": "before-open.session->before-start.session",
      "source": "before-open",
      "sourceHandle": "session",
      "target": "before-start",
      "targetHandle": "session"
    },
    {
      "id": "before-start.session->before-record.session",
      "source": "before-start",
      "sourceHandle": "session",
      "target": "before-record",
      "targetHandle": "session"
    },
    {
      "id": "before-record.recording->before-camera.recording",
      "source": "before-record",
      "sourceHandle": "recording",
      "target": "before-camera",
      "targetHandle": "recording"
    },
    {
      "id": "before-camera.clip->before-stack.in1",
      "source": "before-camera",
      "sourceHandle": "clip",
      "target": "before-stack",
      "targetHandle": "in1"
    },
    {
      "id": "before-label.clip->before-stack.in2",
      "source": "before-label",
      "sourceHandle": "clip",
      "target": "before-stack",
      "targetHandle": "in2"
    },
    {
      "id": "after-session.session->after-open.session",
      "source": "after-session",
      "sourceHandle": "session",
      "target": "after-open",
      "targetHandle": "session"
    },
    {
      "id": "after-open.session->after-start.session",
      "source": "after-open",
      "sourceHandle": "session",
      "target": "after-start",
      "targetHandle": "session"
    },
    {
      "id": "after-start.session->after-record.session",
      "source": "after-start",
      "sourceHandle": "session",
      "target": "after-record",
      "targetHandle": "session"
    },
    {
      "id": "after-record.recording->after-camera.recording",
      "source": "after-record",
      "sourceHandle": "recording",
      "target": "after-camera",
      "targetHandle": "recording"
    },
    {
      "id": "after-camera.clip->after-stack.in1",
      "source": "after-camera",
      "sourceHandle": "clip",
      "target": "after-stack",
      "targetHandle": "in1"
    },
    {
      "id": "after-label.clip->after-stack.in2",
      "source": "after-label",
      "sourceHandle": "clip",
      "target": "after-stack",
      "targetHandle": "in2"
    },
    {
      "id": "before-stack.clip->wipe.a",
      "source": "before-stack",
      "sourceHandle": "clip",
      "target": "wipe",
      "targetHandle": "a"
    },
    {
      "id": "after-stack.clip->wipe.b",
      "source": "after-stack",
      "sourceHandle": "clip",
      "target": "wipe",
      "targetHandle": "b"
    },
    {
      "id": "wipe.clip->render.clip",
      "source": "wipe",
      "sourceHandle": "clip",
      "target": "render",
      "targetHandle": "clip"
    }
  ],
  "markers": []
}

{
  "version": 1,
  "id": "example_changelog",
  "name": "Changelog clip",
  "settings": {
    "width": 1920,
    "height": 1080,
    "fps": 30,
    "theme": "dark",
    "fonts": {
      "main": "Inter",
      "heading": "",
      "code": "JetBrains Mono",
      "families": []
    }
  },
  "variables": {
    "Product name": "Acme",
    "Version": "v2.4"
  },
  "nodes": [
    {
      "id": "title",
      "type": "fx.core.title",
      "position": {
        "x": 0,
        "y": 0
      },
      "params": {
        "eyebrow": "Changelog",
        "title": "What's new in {{Version}}",
        "subtitle": "",
        "mark": "",
        "markLook": "underline",
        "markColor": "#facc15",
        "align": "center",
        "entrance": "rise",
        "color": "#fafafa",
        "accent": "#a78bfa",
        "background": "transparent",
        "fontSize": 112,
        "fontWeight": 760,
        "fontFamily": "",
        "clipDuration": 75,
        "envelope": {}
      }
    },
    {
      "id": "terminal",
      "type": "fx.remocn.terminal-simulator",
      "position": {
        "x": 0,
        "y": 200
      },
      "params": {
        "prompt": "$",
        "title": "~/projects/acme",
        "background": "#0a0a0a",
        "chromeColor": "#1a1a1a",
        "fontSize": 18,
        "charsPerFrame": 1,
        "chunkSize": 1,
        "lines": [
          {
            "text": "deploy --production",
            "type": "command",
            "delay": 0
          },
          {
            "text": "Running tests...",
            "type": "log",
            "delay": 0.2
          },
          {
            "text": "128 tests passed",
            "type": "success",
            "delay": 0.3333
          },
          {
            "text": "Building the image...",
            "type": "log",
            "delay": 0.2667
          },
          {
            "text": "Image ready in 41s",
            "type": "success",
            "delay": 0.3333
          },
          {
            "text": "Rolling out to everyone...",
            "type": "log",
            "delay": 0.2667
          },
          {
            "text": "Live in production",
            "type": "success",
            "delay": 0.4
          }
        ],
        "speed": 1,
        "clipDuration": 150,
        "envelope": {}
      }
    },
    {
      "id": "chart",
      "type": "fx.remocn.animated-bar-chart",
      "position": {
        "x": 0,
        "y": 400
      },
      "params": {
        "barColor": "#0ea5e9",
        "gap": 16,
        "staggerFrames": 0.2,
        "bars": [
          {
            "label": "",
            "value": 35
          },
          {
            "label": "",
            "value": 60
          },
          {
            "label": "",
            "value": 45
          },
          {
            "label": "",
            "value": 80
          },
          {
            "label": "",
            "value": 55
          },
          {
            "label": "",
            "value": 70
          },
          {
            "label": "",
            "value": 90
          },
          {
            "label": "",
            "value": 65
          }
        ],
        "width": 1000,
        "height": 500,
        "baselineColor": "#27272a",
        "labelColor": "#a1a1aa",
        "speed": 1,
        "clipDuration": 120,
        "envelope": {}
      }
    },
    {
      "id": "credit",
      "type": "fx.core.lower-third",
      "position": {
        "x": 300,
        "y": 540
      },
      "params": {
        "title": "{{Product name}} {{Version}}",
        "subtitle": "Out now",
        "position": "bottom-left",
        "accent": "#a78bfa",
        "color": "#fafafa",
        "panel": "rgba(10,10,12,0.72)",
        "fontFamily": "",
        "clipDuration": 120,
        "envelope": {}
      }
    },
    {
      "id": "bg",
      "type": "fx.core.gradient",
      "position": {
        "x": 300,
        "y": 340
      },
      "params": {
        "from": "#1e1b4b",
        "to": "#0f172a",
        "angle": 135,
        "grain": 0.08,
        "clipDuration": 90,
        "envelope": {}
      }
    },
    {
      "id": "chart-scene",
      "type": "timeline.stack",
      "position": {
        "x": 600,
        "y": 340
      },
      "params": {
        "duration": "last",
        "offsetsMs": "",
        "keepLayout": false
      }
    },
    {
      "id": "sequence",
      "type": "timeline.sequence",
      "position": {
        "x": 900,
        "y": 170
      },
      "params": {
        "transition": "core/slide",
        "transitionDuration": 15,
        "keepWhole": false,
        "cuts": []
      }
    },
    {
      "id": "render",
      "type": "output.render",
      "position": {
        "x": 1200,
        "y": 170
      },
      "params": {
        "fileName": "{{Project name}}",
        "codec": "h264",
        "crf": 18,
        "variants": [
          "16:9",
          "1:1"
        ],
        "reframe": "follow",
        "scale": 1,
        "chapters": true,
        "chapterList": false,
        "gl": "angle"
      }
    }
  ],
  "edges": [
    {
      "id": "bg.clip->chart-scene.in1",
      "source": "bg",
      "sourceHandle": "clip",
      "target": "chart-scene",
      "targetHandle": "in1"
    },
    {
      "id": "chart.clip->chart-scene.in2",
      "source": "chart",
      "sourceHandle": "clip",
      "target": "chart-scene",
      "targetHandle": "in2"
    },
    {
      "id": "credit.clip->chart-scene.in3",
      "source": "credit",
      "sourceHandle": "clip",
      "target": "chart-scene",
      "targetHandle": "in3"
    },
    {
      "id": "title.clip->sequence.in1",
      "source": "title",
      "sourceHandle": "clip",
      "target": "sequence",
      "targetHandle": "in1"
    },
    {
      "id": "terminal.clip->sequence.in2",
      "source": "terminal",
      "sourceHandle": "clip",
      "target": "sequence",
      "targetHandle": "in2"
    },
    {
      "id": "chart-scene.clip->sequence.in3",
      "source": "chart-scene",
      "sourceHandle": "clip",
      "target": "sequence",
      "targetHandle": "in3"
    },
    {
      "id": "sequence.clip->render.clip",
      "source": "sequence",
      "sourceHandle": "clip",
      "target": "render",
      "targetHandle": "clip"
    }
  ],
  "markers": []
}

