    "theme": "dark",
    "fonts": {
      "main": "Inter",
      "heading": "",
      "code": "JetBrains Mono",
      "families": []
    }
  },
  "variables": {
    "Site address": "https://demo.playwright.dev/todomvc"
  },
  "nodes": [
    {
      "id": "session",
      "type": "browser.open",
